/// <reference lib="dom" />
/// <reference lib="dom.iterable" />

import { loadFont as loadSans } from "@remotion/google-fonts/Inter";
import {
  AbsoluteFill,
  getRemotionEnvironment,
  Img,
  Interactive,
  type InteractiveBaseProps,
  type InteractiveTransformProps,
  type InteractivitySchema,
  interpolate,
  Sequence,
  type SequenceControls,
  staticFile,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import {
  Children,
  cloneElement,
  type ComponentProps,
  createContext,
  type CSSProperties,
  forwardRef,
  isValidElement,
  type ReactElement,
  type ReactNode,
  type Ref,
  useContext,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import {
  clampChroma,
  converter,
  formatRgb,
  interpolate as culoriInterpolate,
  parse,
  type Rgb,
} from "culori";

/**
 * One object in a scene — a card, a step, a message, a photo — handed to
 * whoever is editing the scene.
 *
 * A scene draws its objects itself: it knows where each one is on every frame.
 * Remotion Studio wants each one as something it can select, outline and edit
 * on its own. `Item` is the seam between the two. The scene wraps the root
 * element of each object in it:
 *
 *   <Item key={i} index={k}>
 *     <div style={…}>…</div>
 *   </Item>
 *
 * With nothing above it — which is every `shadcn add` install and every render
 * on the site — it returns that element untouched: no wrapper, no extra DOM, no
 * behaviour. Inside a Studio Element, an `ItemHost` above it gets the element
 * and the object's index, and can put it inside the object's own `<Sequence>`
 * with the selection outline on that exact node, so the outline moves with the
 * object for its whole animation.
 */
type ItemHost = (index: number, node: ReactElement) => ReactNode;

const ItemHostContext = createContext<ItemHost | null>(null);

const ItemHostProvider = ItemHostContext.Provider;

function Item({
  index,
  primary = true,
  children,
}: {
  /** Which of the scene's objects this is, in the order its props list them. */
  index: number;
  /**
   * False on every copy but one, for a scene that draws the same object more
   * than once (a looping rail): an object has one outline.
   */
  primary?: boolean;
  children: ReactElement;
}): ReactNode {
  const host = useContext(ItemHostContext);
  return host && primary ? host(index, children) : children;
}

const toRgb = converter("rgb");

/**
 * Whether to warn. Read through `globalThis`, never a bare `process`: a Vite
 * project defines no `process`, so the bare name threw a ReferenceError on the
 * very input it meant to warn about — and a stock Remotion project has no Node
 * types, so the bare name was also a type error in every install.
 */
function isDev(): boolean {
  const env = (globalThis as { process?: { env?: { NODE_ENV?: string } } })
    .process?.env;
  return env?.NODE_ENV !== "production";
}

function resolveColorString(s: string): string {
  const trimmed = s.trim();
  if (trimmed.startsWith("var(")) {
    if (isDev()) {
      console.warn(
        `mixOklch cannot resolve CSS variable "${trimmed}" under Remotion's per-frame render. ` +
          "Animated colors must be concrete oklch/hex/rgb values supplied via the theme. " +
          "Falling back to the JS default.",
      );
    }
    return "#000";
  }
  if (!parse(trimmed)) {
    if (isDev()) {
      console.warn(`mixOklch could not parse "${trimmed}"; using black.`);
    }
    return "#000";
  }
  return trimmed;
}

function mixOklch(a: string, b: string, t: number): string {
  const mixed = clampChroma(
    culoriInterpolate(
      [resolveColorString(a), resolveColorString(b)],
      "oklch",
    )(t),
    "oklch",
    "rgb",
  );
  return toCss(toRgb(mixed));
}

function toCss(color: Rgb): string {
  return formatRgb(color);
}

interface KitTheme {
  background: string;
  foreground: string;
  card: string;
  cardForeground: string;
  popover: string;
  popoverForeground: string;
  primary: string;
  primaryForeground: string;
  secondary: string;
  secondaryForeground: string;
  muted: string;
  mutedForeground: string;
  accent: string;
  accentForeground: string;
  destructive: string;
  destructiveForeground: string;
  border: string;
  input: string;
  ring: string;
  radius: number;
  /**
   * The face every text component paints with, as a label from `fonts.ts` or a
   * CSS family the caller has loaded themselves.
   *
   * Optional and defaulted to nothing on purpose: unset, each component keeps
   * the face it was designed around, so adding this token changed no existing
   * render. Set it on `KitUIProvider` and one value re-skins a whole
   * timeline — which is the only reason it lives on the theme rather than
   * staying a per-component prop.
   */
  fontFamily?: string;
}

/**
 * The shadcn token set, as concrete values.
 *
 * ## These are a mirror of `app/globals.css`, and that is the whole point
 *
 * A component we ship lands next to somebody's `Button` and `Input`, and those
 * paint from the CSS custom properties in `globals.css`. A scene that paints
 * from a *different* set of greys is a scene that clashes with the app it was
 * installed into — which is exactly what happened here: this file was written
 * first, `globals.css` was later re-skinned warm, and for a while the site and
 * the videos it sells were two different products.
 *
 * So every value below is the **literal string** from the corresponding
 * `--token` in `app/globals.css` (`:root` for light, `.dark` for dark). Hex, not
 * oklch, purely so that drift is a string comparison — if the two files ever
 * disagree again, `pnpm run check:tokens` says so and prints the pairs.
 *
 * ## Why not just read `var(--token)`?
 *
 * Because a Remotion bundle has none of the app's CSS, so `var()` resolves to
 * nothing under the headless renderer and cannot be interpolated by `mixOklch`
 * at all (see the guard in `color.ts`). Concrete values are not a shortcut here,
 * they are the only thing that survives a render. Users on a different palette
 * override via `KitUIProvider` or a component's `theme` prop.
 *
 * ## `radius` is the one value that flows the other way
 *
 * `globals.css` sets `--radius: 0.28rem` *so that* its `--radius-3xl` step lands
 * on this 10 — see the note beside it there. It is not drift; do not "fix" it.
 */
const defaultLightTheme: KitTheme = {
  background: "#faf9f6", // page — warm off-white
  foreground: "#141414", // text
  card: "#ffffff", // surface on the page
  cardForeground: "#141414",
  popover: "#ffffff",
  popoverForeground: "#141414",
  primary: "#3072db", // accent blue
  primaryForeground: "#ffffff",
  secondary: "#f2f0eb", // subtle fill
  secondaryForeground: "#141414",
  muted: "#f2f0eb",
  mutedForeground: "#6e6a63", // secondary text, leading icons
  accent: "#f2f0eb", // hover wash
  accentForeground: "#141414",
  destructive: "#d92d20",
  // `globals.css` defines no --destructive-foreground; white is the only thing
  // that reads on #d92d20, and shadcn's own default agrees.
  destructiveForeground: "#ffffff",
  border: "#d9d9d9", // hairline
  input: "#d9d9d9",
  ring: "#3072db",
  radius: 10,
};

const defaultDarkTheme: KitTheme = {
  background: "#0a0a0b", // page — near-black
  foreground: "#fafafa", // text
  card: "#141417", // surface, a shade above the page
  cardForeground: "#fafafa",
  popover: "#141417",
  popoverForeground: "#fafafa",
  primary: "#3072db", // the same accent blue in both modes
  primaryForeground: "#ffffff",
  secondary: "#1d1d21", // subtle fill
  secondaryForeground: "#fafafa",
  muted: "#1b1b1f",
  mutedForeground: "#a1a1aa", // secondary text, leading icons
  accent: "#1d1d21", // hover wash
  accentForeground: "#fafafa",
  destructive: "#f97066",
  destructiveForeground: "#fafafa",
  border: "#26272b", // hairline — separation is borders, not shadows
  input: "#26272b",
  ring: "#3072db",
  radius: 10,
};

interface KitThemeContextValue {
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
}

const KitThemeContext = createContext<KitThemeContextValue>({});

function useKitTheme(
  override?: Partial<KitTheme>,
  modeOverride?: "light" | "dark",
): KitTheme {
  const ctx = useContext(KitThemeContext);
  const mode = modeOverride ?? ctx.mode ?? "light";
  const base = mode === "dark" ? defaultDarkTheme : defaultLightTheme;
  return { ...base, ...ctx.theme, ...override };
}

/**
 * A grid of cards that rushes in, settles on a small count, then fills the
 * frame while the number jumps.
 *
 * Five cards and a label; the camera pulls back a fraction, every empty cell
 * around them fills in from the middle out, and the label goes from five to
 * five hundred. It is the "and it scales" shot — one thing, then all of them,
 * without a cut.
 *
 * Beat by beat, measured off the reference at 30fps:
 *
 * | beat | frames | what moves |
 * | --- | --- | --- |
 * | rush in | 0 – 7 | cell pitch 184 → 138, hard horizontal blur |
 * | settle | 7 – 19 | 138 → 121, blur gone by 12 |
 * | label | 11 – 18 | the whole line fades up at once |
 * | drift | 19 – 36 | 121 → 118, still moving, never held |
 * | fill | 37 – 46 | 118 → 96.5, every cell populates, 5 → 500 |
 *
 * The pull-back is a *scale*, not a camera z-move: the two centre columns hold
 * their midpoint at x 358.5 for all 47 frames while the pitch between them
 * walks 138.5 → 96.5, and the cards keep a constant fraction of the cell. And
 * the settle never actually settles — the pitch is still shedding a fifth of a
 * pixel per frame at frame 37, which is what stops the middle of the shot
 * looking like a freeze-frame.
 */

const { fontFamily: SANS } = loadSans();

/* ─────────────────────────────────────────────────────────────────────────
   Geometry, in the reference's own 712×398 pixels
   ───────────────────────────────────────────────────────────────────────── */

const REF_W = 712;
const REF_H = 398;

/**
 * What the pull-back scales about.
 *
 * Horizontally it is the midpoint the two centre columns hold all clip: 358.75.
 * Vertically it is *not* the middle row — the centre row's own middle sits at
 * 202.5 and moves to 203.5 as the grid shrinks, which puts the fixed point 5px
 * lower, at 207.6. Scaling about the row instead leaves the whole grid a
 * pixel high through the entire fill.
 */
const ORIGIN = { x: 358.75, y: 207.6 };

/**
 * One cell at scale 1, and how much of it the card takes.
 *
 * The *cell* is measured — 120.5 × 147, the pitch the whole pull-back is fitted
 * to. The card inside it is a design choice and it is deliberately not the
 * reference's: measured, that card is 90.5 × 117 with a 30px gutter and a 6px
 * radius, which reads as a scatter of small rounded stickers. This one fills
 * 95% of its cell with a 3px corner, so the grid reads as a wall of frames.
 */
const CELL = { w: 120.5, h: 147 };
const CARD = { w: 114.5, h: 139.5, radius: 3 };

/**
 * How much closer the grid sits than the reference's camera.
 *
 * One, now. It was 1.75 for exactly as long as it took to find out that the
 * cards were being *drawn* at reference-pixel size inside cells laid out at
 * render-pixel size — 0.42 of their own cell rather than 0.95 — and that no
 * amount of zoom fixes a missing unit conversion, it only moves the error into
 * the cell spacing as well. Left in place because it is the honest knob if the
 * grid should ever sit closer than the reference's, and because a `1` with this
 * note attached is cheaper than someone rediscovering the bug.
 */
const GRID_ZOOM = 1;

/** A column *boundary* sits on the centre; a row *centre* does. */
const COL_EDGE = 359;
const ROW_MID = 202.5;

/**
 * The five that are there before the grid fills.
 *
 * `[col, row]`, with column 0 immediately right of the centre boundary and row
 * 0 the middle row. Four make a square around the label and the fifth hangs
 * below on the right — an even 2×2 reads as a swatch, and the odd one out is
 * what makes it read as a handful of people.
 */
const SEED: readonly (readonly [number, number])[] = [
  [-1, -1],
  [0, -1],
  [-1, 0],
  [0, 0],
  [0, 1],
];

/** The label, at scale 1. */
const LABEL = {
  cy: ROW_MID,
  size: 30,
  padX: 15,
  height: 41,
  radius: 9,
};

/* ─────────────────────────────────────────────────────────────────────────
   Curves
   ───────────────────────────────────────────────────────────────────────── */

/** When the grid stops being five cards and becomes all of them. */
const FILL_AT = 37;

/**
 * The cell pitch, in reference px — the one number the whole scene hangs on.
 *
 * Tracked as the distance between the two centre columns: 138.5 at frame 7,
 * 128 at 11, 121.5 at 19, 120 at 26, 118 from 32 to 36, then 113, 104, 99.5,
 * 96.5 across the fill. Before frame 7 the horizontal blur is wider than a card
 * and nothing can be measured, so that stretch is the same exponential run
 * backwards, which puts frame 0 at 174 — a card and a half outside the frame.
 *
 * Knots, not that exponential. Two of them fitted the settle and the fill to
 * within a pixel and a half each, which is a pixel and a half of grid, and they
 * met 3.7px apart at the switch going the *wrong way* — the pitch grew by 0.17
 * between 36 and 37, so the grid jolted outward on the exact frame it was
 * supposed to start collapsing. Every knot below is a measured frame and the
 * table is strictly decreasing, so it cannot do that.
 *
 * Every frame number here is zero-based, and every one of them was read off a
 * file called `f0NN.png` that is one-based: `f038.png` is frame 37. Taking the
 * filenames at face value put the whole clip a frame late and cost the switch
 * frame alone 17 mean.
 */
function pitch(t: number, fps = 30): number {
  return interpolate(
    t * fps,
    [
      0, 7, 9, 11, 13, 15, 17, 19, 22, 26, 29, 31, 36, 37, 38, 39, 40, 41, 42,
      43, 45, 46,
    ],
    [
      174, 138.5, 132, 128, 125, 124, 122.5, 121.5, 120, 119.6, 119, 118.5, 118,
      117.9, 113, 106, 104, 102, 99.5, 97.5, 96.6, 96.5,
    ],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" },
  );
}

/** The pitch as a multiple of the cell, which is what everything scales by. */
function gridScale(t: number, fps = 30): number {
  return pitch(t, fps) / CELL.w;
}

/**
 * The horizontal blur, in reference px.
 *
 * Measured as the frame's own horizontal gradient, which is what a smear
 * actually costs: 0.28 at frame 3, 1.90 at 4, 2.75 at 5, and then flat for ten
 * frames while it creeps to 3.18. So the blur is spent inside five frames and
 * the long ease that follows it is sharp.
 *
 * The first cut derived this from the pull-back's own speed, on the theory that
 * a blur and its motion should not be able to disagree. They can: the motion is
 * still shedding two pixels of pitch a frame at frame 8 and the reference is
 * already sharp there, so the derivative kept a smear on screen for seven
 * frames the reference does not have, and cost those frames 3 mean each.
 */
function entryBlur(t: number, fps = 30): number {
  return interpolate(t * fps, [0, 2, 3, 4, 5], [22, 14, 6, 2, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
}

/**
 * The one card that arrives late, in reference px of extra smear.
 *
 * The scene's own blur is spent by frame 5, but the card behind the label is
 * still a horizontal streak at 7 and only lands around 9 — every other card is
 * sharp and at scale by 5. It is the detail that makes the entry read as five
 * separate things arriving rather than one picture being pushed in, and it is
 * the only per-card timing in the piece.
 */
const LATE_CARD: readonly [number, number] = [-1, 0];

function lateBlur(t: number, fps = 30): number {
  return interpolate(t * fps, [3, 5, 7, 9], [26, 17, 7, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
}

/** The label fading up, all of it at once. */
function labelIn(t: number, fps = 30): number {
  return interpolate(t * fps, [11, 13, 15, 17, 18], [0, 0.22, 0.55, 0.9, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
}

/**
 * How present a cell is.
 *
 * `ring` is the Chebyshev distance to the nearest seed cell, so the ring
 * touching the five arrives first and each one after it a frame later. That
 * ordering is measured: at frame 37 exactly two new columns exist, either side
 * of the original two, and by 38 there are eight.
 */
function cellIn(ring: number, t: number, fps = 30): number {
  if (ring === 0) return 1;
  // Half a frame per ring and two frames each: the reference is 90% done in
  // three frames — 20.3, 19.0, 19.8 mean change and then a decay — and a
  // ring-per-frame stagger over three turned that into a five-frame ramp that
  // peaked two frames after the reference had finished.
  // The ramp *straddles* the switch frame rather than starting on it: at frame
  // 37 the reference's first new columns are already half there — 80px wide
  // against a settled 90 — so a ring that is still zero on 37 arrives a whole
  // frame late and the change profile peaks two frames after the reference's.
  //
  // A whole frame of stagger, not half. On frame 37 the reference has ring one
  // and nothing else; by 38 it has rings one and two, the second of them
  // narrower than the first. Half a frame put ring two on screen a frame early
  // and drew cards where the reference still had page.
  const at = FILL_AT - 1 + (ring - 1);
  return interpolate(t * fps, [at, at + 1.5], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
}

/** Chebyshev distance from a cell to the nearest of the five. */
function ringOf(col: number, row: number): number {
  let best = Number.POSITIVE_INFINITY;
  for (const [c, r] of SEED) {
    best = Math.min(best, Math.max(Math.abs(col - c), Math.abs(row - r)));
  }
  return best;
}

/* ─────────────────────────────────────────────────────────────────────────
   Component
   ───────────────────────────────────────────────────────────────────────── */

export interface CountGridProps {
  /** What the label counts, before the grid fills and after. */
  from?: string;
  to?: string;
  /** The noun after the number. */
  noun?: string;
  /** Card images, cycled across the grid. Anything `<Img>` can load. */
  cards?: string[];
  /** Defaults to the theme's `background`. */
  background?: string;
  /**
   * The label's ink, left end and right end of its gradient. Default to
   * `primary` walked halfway toward `foreground`, then `primary` — the navy →
   * blue the reference had, but one that turns pale in dark mode instead of
   * vanishing into it.
   */
  inkFrom?: string;
  inkTo?: string;
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
  /** 1 is the measured speed. */
  speed?: number;
}
// index 0, 2, 4 … are ART by construction, and the five seed cells only ever
// reach the first `SEED.length` of them.

/**
 * A root-relative asset is a `public/` file. Only the site's own Player serves
 * it at that path; Remotion Studio and a render know its URL through
 * `staticFile()` alone — so every environment but the Player rewrites it.
 */
function resolveSrc(src: string): string {
  const isLocal = src.startsWith("/") && !src.startsWith("//");
  if (!isLocal || getRemotionEnvironment().isPlayer) return src;
  // A value that already came out of staticFile() carries the static base
  // (`/static-<hash>/…`); running it through again would prefix it twice.
  const base = staticFile("_").slice(0, -2);
  if (base && src.startsWith(`${base}/`)) return src;
  try {
    return staticFile(src.replace(/^\/+/, ""));
  } catch {
    return src;
  }
}

function CountGridScene({
  from = "5",
  to = "500",
  noun = "clips",
  cards = CountGridDefaults.cards,
  background,
  inkFrom,
  inkTo,
  speed = 1,
  theme,
  mode,
}: CountGridProps) {
  const t = useKitTheme(theme, mode);
  const page = background ?? t.background;
  const ink0 = inkFrom ?? mixOklch(t.primary, t.foreground, 0.5);
  const ink1 = inkTo ?? t.primary;
  // The card edge is half a hairline: forty full-strength borders read as a
  // grid of boxes, not a wall of frames.
  const cardEdge = mixOklch(t.card, t.border, 0.5);
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const now = frame / fps / (speed || 1);

  const k = Math.min(width / REF_W, height / REF_H);
  const ox = (width - REF_W * k) / 2;
  const oy = (height - REF_H * k) / 2;

  const s = gridScale(now, fps);
  // The cards live one zoom step closer than everything else — see GRID_ZOOM.
  const g = s * GRID_ZOOM;
  const blur = entryBlur(now, fps) * k;
  const late = lateBlur(now, fps) * k;
  const label = labelIn(now, fps);

  // Everything is laid out at scale 1 and then scaled about ORIGIN, so a cell's
  // place in the grid never depends on the zoom — only its size does.
  const at = (v: number, origin: number, scale = s) =>
    (v - origin) * scale + origin;
  // `cellW`/`cellH` stay in reference px — they are only ever compared against
  // REF_W/REF_H to count how many cells reach the frame.
  const cellW = CELL.w * g;
  const cellH = CELL.h * g;
  // The card's size is drawn, so it needs `k` — the same reference→render scale
  // its own position already goes through. Without it the card was laid out in
  // reference px inside a cell laid out in render px: 0.42 of its cell on a
  // 1280-wide render instead of 0.95, which is every "the images are too small
  // and too far apart" note in one bug.
  const cardW = CARD.w * g * k;
  const cardH = CARD.h * g * k;

  // How many cells reach the frame at this scale, plus one so nothing pops in
  // at the edge.
  const cols = Math.ceil(REF_W / cellW / 2) + 2;
  const rows = Math.ceil(REF_H / cellH / 2) + 2;

  const cells: {
    col: number;
    row: number;
    x: number;
    y: number;
    o: number;
    i: number;
    src: string;
  }[] = [];
  for (let row = -rows; row <= rows; row++) {
    for (let col = -cols; col <= cols; col++) {
      const o = cellIn(ringOf(col, row), now, fps);
      if (o <= 0) continue;
      const cx = at(COL_EDGE + (col + 0.5) * CELL.w, ORIGIN.x, g) * k + ox;
      const cy = at(ROW_MID + row * CELL.h, ORIGIN.y, g) * k + oy;
      if (cx < -cardW || cx > width + cardW) continue;
      if (cy < -cardH || cy > height + cardH) continue;
      // A stable, well-mixed index: neighbours must not share a card or the
      // grid reads as wallpaper.
      //
      // `cards` alternates the two kinds, so its even slots are the ones with
      // pictures on them. The five that carry the whole first half of the shot
      // take only those; everything else takes the mix. Sharing one index put
      // three of the five on registry stills — 16:9 scenes of dark text on
      // white, cropped to 3:4 — and the hero moment was two blank cards and a
      // label.
      const mix = col * 7 + row * 13;
      // `col * 2 + row` is the one small combination that is injective over the
      // five seed cells modulo five — 7/13 sends (-1,-1) and (0,0) to the same
      // slot, and the two cards diagonally across the label came out identical.
      const seed = col * 2 + row;
      const i =
        ringOf(col, row) === 0
          ? (2 * (((seed % SEED.length) + SEED.length) % SEED.length)) %
            cards.length
          : ((mix % cards.length) + cards.length) % cards.length;
      cells.push({ col, row, x: cx, y: cy, o, i, src: cards[i] ?? "" });
    }
  }

  // The grid cycles `cards`, so one card is drawn many times. Studio outlines
  // the copy nearest the middle of the frame; the others are only pictures of
  // it.
  const nearest = new Map<number, (typeof cells)[number]>();
  const off = (c: (typeof cells)[number]) =>
    Math.hypot(c.x - width / 2, c.y - height / 2);
  for (const c of cells) {
    const held = nearest.get(c.i);
    if (!held || off(c) < off(held)) nearest.set(c.i, c);
  }

  const filled = now * fps >= FILL_AT;
  const pillH = LABEL.height * s * k;

  return (
    <AbsoluteFill
      showInTimeline={false}
      style={{
        backgroundColor: page,
        fontFamily: SANS,
        overflow: "hidden",
      }}
    >
      {/* A directional blur: the motion is horizontal, and CSS `blur()` is
          round, so it softens the card's top and bottom edges — which are not
          moving — as much as its sides. */}
      <svg width={0} height={0} style={{ position: "absolute" }} aria-hidden>
        <title>Motion blur</title>
        <filter
          id="count-grid-smear"
          x="-40%"
          y="-10%"
          width="180%"
          height="120%"
        >
          <feGaussianBlur stdDeviation={`${blur} 0`} />
        </filter>
        <filter
          id="count-grid-late"
          x="-90%"
          y="-10%"
          width="280%"
          height="120%"
        >
          <feGaussianBlur stdDeviation={`${late} 0`} />
        </filter>
      </svg>

      <div
        style={{
          position: "absolute",
          inset: 0,
          filter: blur > 0.35 ? "url(#count-grid-smear)" : undefined,
          ...(getRemotionEnvironment().isRendering
            ? null
            : { willChange: "filter" as const }),
        }}
      >
        {cells.map((c) => (
          <Item
            key={`${c.col},${c.row}`}
            index={c.i}
            primary={nearest.get(c.i) === c}
          >
            <div
              style={{
                position: "absolute",
                left: c.x - cardW / 2,
                top: c.y - cardH / 2,
                width: cardW,
                height: cardH,
                borderRadius: CARD.radius * g * k,
                overflow: "hidden",
                background: t.card,
                // A hairline, not a shadow: a drop shadow under forty white
                // tiles on a white page is forty grey smears.
                boxShadow: `inset 0 0 0 ${Math.max(0.5, 0.9 * g * k)}px ${cardEdge}`,
                display: "flex",
                alignItems: "center",
                opacity: c.o,
                filter:
                  late > 0.35 &&
                  c.col === LATE_CARD[0] &&
                  c.row === LATE_CARD[1]
                    ? "url(#count-grid-late)"
                    : undefined,
              }}
            >
              {c.src ? (
                <Img
                  showInTimeline={false}
                  src={resolveSrc(c.src)}
                  style={{
                    width: cardW,
                    height: cardH,
                    // Preflight's `img { max-width: 100% }` against a box that
                    // sizes from its content is 100% of nothing — the card
                    // renders zero px wide on the site and perfectly in the mp4.
                    maxWidth: "none",
                    objectFit: "cover",
                  }}
                  alt=""
                />
              ) : null}
            </div>
          </Item>
        ))}
      </div>

      <div
        style={{
          position: "absolute",
          left: 0,
          right: 0,
          top: at(LABEL.cy, ORIGIN.y) * k + oy - pillH / 2,
          display: "flex",
          justifyContent: "center",
          opacity: label,
        }}
      >
        <div
          style={{
            display: "flex",
            alignItems: "center",
            height: pillH,
            padding: `0 ${LABEL.padX * s * k}px`,
            borderRadius: LABEL.radius * s * k,
            background: t.card,
            border: `1px solid ${t.border}`,
            // Not a drop shadow: on a white page under a white pill it reads as
            // a grey smear, and the reference has a hairline and nothing else.
            boxShadow: "none",
            fontSize: LABEL.size * s * k,
            fontWeight: 400,
            lineHeight: 1,
            whiteSpace: "nowrap",
            color: ink0,
            textRendering: "geometricPrecision",
          }}
        >
          <span
            style={{
              backgroundImage: `linear-gradient(90deg, ${ink0} 0%, ${ink1} 100%)`,
              WebkitBackgroundClip: "text",
              backgroundClip: "text",
              color: "transparent",
              paddingBottom: 0.14 * LABEL.size * s * k,
            }}
          >
            {filled ? to : from} {noun}
          </span>
        </div>
      </div>
    </AbsoluteFill>
  );
}

/* ─────────────────────────────────────────────────────────────────────────
   Remotion Studio: one card at a time
   ───────────────────────────────────────────────────────────────────────── */

/**
 * Everything `el` paints that can be seen, in page pixels: its text runs, its
 * media, and every box with a fill or a border, each cut to every box that
 * clips it up to and including `root` (the Element's own box). Null when none
 * of it shows — transparent, or clipped out of the Element.
 */
function CountGridPainted(
  el: Element,
  root: Element,
): [number, number, number, number] | null {
  let u: [number, number, number, number] | null = null;
  const add = (r: DOMRect, from: Element) => {
    // Never past the Element's own box, clipped or not: a text run's line box
    // stands above its ink, and no scene's ink leaves its box (measured).
    const c0 = root.getBoundingClientRect();
    let b: [number, number, number, number] = [
      Math.max(r.left, c0.left),
      Math.max(r.top, c0.top),
      Math.min(r.right, c0.right),
      Math.min(r.bottom, c0.bottom),
    ];
    let alpha = 1;
    for (
      let a: Element | null = from;
      a;
      a = a === root ? null : a.parentElement
    ) {
      const cs = getComputedStyle(a);
      if (cs.visibility === "hidden") return;
      alpha *= Number(cs.opacity);
      if (a !== from && a !== root && cs.overflow !== "visible") {
        const c = a.getBoundingClientRect();
        b = [
          Math.max(b[0], c.left),
          Math.max(b[1], c.top),
          Math.min(b[2], c.right),
          Math.min(b[3], c.bottom),
        ];
      }
    }
    if (alpha < 0.02 || b[2] <= b[0] || b[3] <= b[1]) return;
    u = u
      ? [
          Math.min(u[0], b[0]),
          Math.min(u[1], b[1]),
          Math.max(u[2], b[2]),
          Math.max(u[3], b[3]),
        ]
      : b;
  };
  const walk = (e: Element) => {
    const cs = getComputedStyle(e);
    if (cs.display === "none") return;
    const media = /^(img|video|canvas|svg)$/i.test(e.tagName);
    if (
      media ||
      cs.backgroundColor !== "rgba(0, 0, 0, 0)" ||
      cs.backgroundImage !== "none" ||
      parseFloat(cs.borderTopWidth) > 0
    )
      add(e.getBoundingClientRect(), e);
    if (media) return;
    for (const n of Array.from(e.childNodes)) {
      if (n.nodeType === Node.TEXT_NODE && n.textContent?.trim()) {
        const range = document.createRange();
        range.selectNodeContents(n);
        for (const r of Array.from(range.getClientRects())) add(r, e);
      } else if (n.nodeType === Node.ELEMENT_NODE) walk(n as Element);
    }
  };
  walk(el);
  return u;
}

/** Whether every box that clips `el`, up to `root`, leaves all of it showing. */
function CountGridWhole(el: Element, root: Element): boolean {
  const r = el.getBoundingClientRect();
  for (let a = el.parentElement; a; a = a === root ? null : a.parentElement) {
    if (getComputedStyle(a).overflow === "visible") continue;
    const c = a.getBoundingClientRect();
    if (
      r.left < c.left - 1 ||
      r.top < c.top - 1 ||
      r.right > c.right + 1 ||
      r.bottom > c.bottom + 1
    )
      return false;
  }
  return true;
}
type CountGridCardValues = {
  readonly image?: string;
};

type CountGridCardProps = InteractiveBaseProps &
  Omit<InteractiveTransformProps, "style"> &
  CountGridCardValues & {
    readonly style?: CSSProperties | null;
    /** The node the scene draws this card as, while it draws it; set by the stage, never by hand. */
    readonly claim?: { current: Element | null };
    /** The box its outline falls back to when the node is not all there; set by the stage too. */
    readonly slot?: { current: HTMLDivElement | null };
    /** Hands Studio's live props back to the stage, which draws the node; set by the stage too. */
    readonly report?: (state: CountGridCardState) => void;
  };

/** What Studio is doing to one card right now, which the stage applies to its node. */
type CountGridCardState = {
  values: CountGridCardValues;
  style?: CSSProperties;
  hidden?: boolean;
  from?: number;
  durationInFrames?: number;
};

const CountGridCardSchema = {
  ...Interactive.baseSchema,
  image: {
    type: "asset",
    assetType: "image",
    default: undefined,
    description: "Image",
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

/**
 * One card: its layer in Studio. The scene decides where it is on every
 * frame and draws it; this is the Sequence Studio lists, selects and outlines,
 * mounted for the Element's whole length so the layer never leaves the
 * timeline while the card is off the frame. It draws nothing itself: its
 * values, transform, visibility and timing reach the node through the stage.
 */
const CountGridCardInner = forwardRef<
  Element,
  CountGridCardProps & { readonly controls: SequenceControls | undefined }
>(
  (
    {
      controls,
      name,
      style,
      from,
      durationInFrames,
      trimBefore,
      playbackRate,
      loop,
      freeze,
      hidden,
      showInTimeline,
      claim,
      slot,
      report,
      image,
    },
    ref,
  ) => {
    // What Studio outlines, chosen every frame: the node itself — its exact
    // quad, transforms and all — while all of it shows; a box over the part
    // that does when the Element clips it or it paints past its own box; nothing while none of it
    // shows, so an object that has left is not still selectable where it was.
    const target = useRef<Element | null>(null);
    // Re-rendered every frame, so the outline is chosen for every frame: the
    // scene moves the node without re-rendering this layer.
    useCurrentFrame();
    // Studio reads the ref every time it measures.
    const outline = useRef({
      get current() {
        return target.current ?? claim?.current ?? null;
      },
    }).current;
    // Studio's live props arrive here — a value being typed, a transform being
    // dragged, the layer hidden or retimed — and the stage draws the node.
    useLayoutEffect(() => {
      report?.({
        values: { image },
        style: style ?? undefined,
        hidden,
        from,
        durationInFrames,
      });
    });
    useImperativeHandle(ref, () => claim?.current as Element);
    useLayoutEffect(() => {
      // Outlines are a Studio thing; a render or the Player measures nothing.
      if (!getRemotionEnvironment().isStudio) return;
      const box = slot?.current;
      const root = box?.parentElement;
      if (!box || !root) return;
      const el = claim?.current;
      const b = el ? CountGridPainted(el, root) : null;
      if (!el || !b) {
        box.style.display = "none";
        target.current = box;
        return;
      }
      const n = el.getBoundingClientRect();
      if (
        CountGridWhole(el, root) &&
        b[0] >= n.left - 1 &&
        b[1] >= n.top - 1 &&
        b[2] <= n.right + 1 &&
        b[3] <= n.bottom + 1
      ) {
        box.style.display = "none";
        target.current = el;
        return;
      }
      const r = root.getBoundingClientRect();
      const k = root.offsetWidth / (r.width || 1);
      box.style.display = "block";
      box.style.left = `${(b[0] - r.left) * k}px`;
      box.style.top = `${(b[1] - r.top) * k}px`;
      box.style.width = `${(b[2] - b[0]) * k}px`;
      box.style.height = `${(b[3] - b[1]) * k}px`;
      target.current = box;
    });
    return (
      <Sequence
        layout="none"
        from={from}
        durationInFrames={durationInFrames}
        trimBefore={trimBefore}
        playbackRate={playbackRate}
        loop={loop}
        freeze={freeze}
        hidden={hidden}
        showInTimeline={showInTimeline}
        name={name ?? "Card"}
        controls={controls}
        outlineRef={outline}
      />
    );
  },
);

const CountGridCard = Interactive.withSchema({
  Component: CountGridCardInner,
  componentName: "<CountGridCard>",
  schema: CountGridCardSchema,
  supportsEffects: false,
});

type CountGridStageProps = InteractiveBaseProps &
  Omit<ComponentProps<typeof CountGridScene>, "from" | "cards"> & {
    readonly start?: ComponentProps<typeof CountGridScene>["from"];
    readonly children?: ReactNode;
  };

/**
 * What a scene prop falls back to when Studio does not pass it, reset included.
 * The cards' own lists are here only for the scene's parameter defaults;
 * the stage always passes the ones its children build.
 */
const CountGridDefaults = {
  start: "5",
  to: "500",
  noun: "clips",
  mode: "light",
  speed: 1,
  background: "transparent",
  cards: [
    staticFile("count-grid/photo-1.webp"),
    staticFile("count-grid/photo-2.webp"),
    staticFile("count-grid/photo-3.jpg"),
    staticFile("count-grid/photo-4.jpg"),
    staticFile("count-grid/photo-5.jpg"),
    staticFile("count-grid/photo-6.jpg"),
    staticFile("count-grid/photo-7.jpg"),
    staticFile("count-grid/photo-8.jpg"),
  ],
} satisfies Partial<CountGridStageProps> &
  Partial<Pick<ComponentProps<typeof CountGridScene>, "cards">>;

const CountGridStageSchema = {
  ...Interactive.baseSchema,
  start: { type: "text-content", default: "5", description: "Count before" },
  to: { type: "text-content", default: "500", description: "Count after" },
  noun: { type: "text-content", default: "clips", description: "Noun" },
  mode: {
    type: "enum",
    default: "light",
    description: "Mode",
    variants: { light: {}, dark: {} },
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
    keyframable: false,
  },
} as const satisfies InteractivitySchema;

/** The scene's props, from its cards' values in order. */
const CountGridFromItems = (o: readonly CountGridCardValues[]) => ({
  cards: o.map((x) => x.image ?? ""),
});

/**
 * In over the first frames, out over the last. Opacity only: nothing moves, so
 * no glyph can snap to the pixel grid on the way out.
 */
function CountGridFade({ children }: { children: ReactNode }) {
  const frame = useCurrentFrame();
  const enter = Math.min(1, (frame + 1) / 6);
  const { durationInFrames } = useVideoConfig();
  const left = Math.min(1, Math.max(0, (durationInFrames - 1 - frame) / 12));
  const leave = left * left;
  return (
    <AbsoluteFill showInTimeline={false} style={{ opacity: enter * leave }}>
      {children}
    </AbsoluteFill>
  );
}

/** The host, told the frame inside the Element — the one its layers' timing is in. */
function CountGridHosted({
  host,
  children,
}: {
  host: (frame: number) => ItemHost;
  children: ReactNode;
}) {
  return (
    <ItemHostProvider value={host(useCurrentFrame())}>
      {children}
    </ItemHostProvider>
  );
}

/**
 * The scene, with its cards as children. It reads their values to lay
 * the scene out, and hands each one back the node the scene draws it as.
 */
const CountGridStageInner = forwardRef<
  HTMLDivElement,
  CountGridStageProps & { readonly controls: SequenceControls | undefined }
>(
  (
    {
      controls,
      name,
      from,
      durationInFrames,
      trimBefore,
      playbackRate,
      loop,
      freeze,
      hidden,
      showInTimeline,
      children,
      ...props
    },
    ref,
  ) => {
    const outlineRef = useRef<HTMLDivElement>(null);
    useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
    // One empty box per card on the stage: the outline it falls back to,
    // which it moves over the part of itself that shows.
    const slots = useRef<{ current: HTMLDivElement | null }[]>([]);
    const slotFor = (i: number) => {
      slots.current[i] ??= { current: null };
      return slots.current[i];
    };
    // Every card the file lists, by position: each keeps its layer.
    const all = Children.toArray(children).filter(
      isValidElement,
    ) as ReactElement<CountGridCardProps>[];
    const claims = useRef<{ current: Element | null }[]>([]);
    const claimFor = (j: number) => {
      claims.current[j] ??= { current: null };
      return claims.current[j];
    };
    const { start, ...rest } = { ...CountGridDefaults, ...props };
    // What Studio is doing to each card that the file may not have yet.
    const [live, setLive] = useState<Record<number, CountGridCardState>>({});
    const report = (j: number, state: CountGridCardState) =>
      setLive((prev) =>
        JSON.stringify(prev[j]) === JSON.stringify(state)
          ? prev
          : { ...prev, [j]: state },
      );
    const merged = all.map((o, j) => {
      const st = live[j];
      return st
        ? {
            ...o.props,
            ...st.values,
            style: st.style,
            hidden: st.hidden,
            from: st.from,
            durationInFrames: st.durationInFrames,
          }
        : o.props;
    });
    // The ones the scene draws, in its order: the positions its `Item`s index.
    const kept = all.map((_, j) => j);
    const built = CountGridFromItems(
      kept.map((j) => merged[j] as CountGridCardValues),
    );
    const host =
      (frame: number): ItemHost =>
      (index, node) => {
        const j = kept[index];
        const m = j === undefined ? undefined : merged[j];
        if (j === undefined || !m) return node;
        // The layer's own visibility and timing, which its Sequence would apply
        // if it held the node.
        const start = m.from ?? 0;
        if (
          m.hidden ||
          frame < start ||
          frame >= start + (m.durationInFrames ?? Number.POSITIVE_INFINITY)
        )
          return null;
        const own = node as ReactElement<{
          ref?: Ref<Element>;
          style?: CSSProperties;
        }>;
        return cloneElement(own, {
          ref: claimFor(j),
          style: { ...own.props.style, ...m.style },
        });
      };
    // The scene measures its copy once, on mount, so a saved edit remounts it.
    // An edit still being typed does not: the scene would restart on every
    // keystroke. The layers are outside it and never remount with it.
    const key = JSON.stringify({
      ...rest,
      ...CountGridFromItems(all.map((o) => o.props)),
    });
    return (
      <Sequence
        layout="none"
        from={from}
        durationInFrames={durationInFrames}
        trimBefore={trimBefore}
        playbackRate={playbackRate}
        loop={loop}
        freeze={freeze}
        hidden={hidden}
        showInTimeline={showInTimeline}
        name={name ?? "Count Grid"}
        controls={controls}
        outlineRef={outlineRef}
        width={1280}
        height={720}
      >
        <div
          ref={outlineRef}
          style={{
            position: "relative",
            width: 1280,
            height: 720,
            overflow: "hidden",
            color: "black",
            fontFamily: "initial",
            fontSize: 16,
            fontStyle: "normal",
            fontVariant: "normal",
            fontWeight: 400,
            fontStretch: "normal",
            fontKerning: "auto",
            fontFeatureSettings: "normal",
            fontVariationSettings: "normal",
            lineHeight: "normal",
            letterSpacing: "normal",
            wordSpacing: "normal",
            textAlign: "start",
            textIndent: 0,
            textTransform: "none",
            textShadow: "none",
            textRendering: "auto",
            whiteSpace: "normal",
            wordBreak: "normal",
            overflowWrap: "normal",
            hyphens: "manual",
            direction: "ltr",
            visibility: "visible",
          }}
        >
          {/* First, so each box's ref is set before the objects that move it
              run their layout effects on a fresh mount. */}
          {all.map((_, j) => (
            <div
              // biome-ignore lint/suspicious/noArrayIndexKey: one box per position
              key={j}
              ref={slotFor(j)}
              style={{
                position: "absolute",
                display: "none",
                pointerEvents: "none",
                opacity: 0,
              }}
            />
          ))}
          <CountGridFade>
            <CountGridHosted host={host}>
              <CountGridScene key={key} {...rest} {...built} from={start} />
            </CountGridHosted>
          </CountGridFade>
          {/* The layers, after the scene: its nodes are attached by the time
              they measure them. */}
          {all.map((o, j) =>
            cloneElement(o, {
              // biome-ignore lint/suspicious/noArrayIndexKey: one layer per position
              key: j,
              claim: claimFor(j),
              slot: slotFor(j),
              report: (state: CountGridCardState) => report(j, state),
            }),
          )}
        </div>
      </Sequence>
    );
  },
);

